/**
 * Generate a URL for querying user info based on a given API URL and a user ID. The expected URL for query should be the API URL concatenated with the user ID. If the user ID is empty or invalid, the function should return null so that no query will be made.
 * Examples:
 * - getUrlForQuery('https://example.com/api/user', 'aBc123') returns 'https://example.com/api/user/aBc123'
 * - getUrlForQuery('https://example.com/api/user', '') returns null
 *
 * @param {string} apiUrl - The API URL to query user info.
 * @param {string} userId - The user ID to query.
 * @returns {string|null} - The URL for query.
 */
function getUrlForQuery(apiUrl, userId) {
  // Validate userId: return null if it's null, undefined, an empty string, or a string of only whitespace.
  // The JSDoc specifies userId as a string, so userId.trim() is expected to be safe after the !userId check.
  if (!userId || userId.trim() === '') {
    return null;
  }

  // Ensure the apiUrl ends with a slash to correctly form a path segment for the userId.
  // This aligns with the provided example where 'https://example.com/api/user' becomes 'https://example.com/api/user/aBc123'.
  const normalizedApiUrl = apiUrl.endsWith('/') ? apiUrl : apiUrl + '/';

  // Concatenate the normalized API URL with the user ID to form the final query URL.
  // Per the problem statement and examples, no URL encoding is applied to userId.
  return normalizedApiUrl + userId;
}
```

